package gen

import (
	"fmt"
	"go/format"
	"strconv"
	"strings"
)

// header starts both generated files: the SPDX line, then the marker Go tools recognise.
const header = "// SPDX-License-Identifier: Apache-2.0\n\n// Code generated by catalogen. DO NOT EDIT.\n\n"

// Pieces of the rendered source written in more than one place.
const (
	closeBlock = "}\n\n"
	entryLine  = "\t%s: {%s},\n"
	prefixRes  = "Resource"
)

// Names of the identifier types RenderIDs declares.
const (
	typeAction       = "Action"
	typeEventType    = "EventType"
	typeOp           = "Op"
	typeResourceKind = "ResourceKind"
	typeChannelOp    = "ChannelOp"
)

// generatedNames are the exported names RenderIDs declares besides the constants.
var generatedNames = []string{
	typeAction, typeEventType, typeOp, typeResourceKind, typeChannelOp,
	"ParseAction", "ParseEventType", "ParseOp", "ParseResourceKind", "ParseChannelOp",
	"AllActions", "AllEventTypes", "AllOps", "AllResourceKinds", "AllChannelOps",
}

// idKind describes one identifier type of the ids file.
type idKind struct {
	typeName, prefix, what, doc string
	plural, parseName, allName  string
	ids, idents                 []string
}

// RenderIDs renders internal/kernel/authorize/catalog_ids_gen.go: the identifier types, one
// constant per catalogue entry and the Parse and All functions.
func RenderIDs(c *Catalog) ([]byte, error) {
	var actions, events, ops, kinds, channelOps []string
	for _, a := range c.Actions {
		actions = append(actions, a.ID)
	}
	for _, e := range c.Events {
		events = append(events, e.Type)
	}
	for _, o := range c.Ops {
		ops = append(ops, o.Op)
	}
	kinds = append(kinds, c.ResourceKinds...)
	var channelIdents []string
	for _, o := range c.ChannelOps {
		channelOps = append(channelOps, o.Channel+"/"+o.Op)
		channelIdents = append(channelIdents, channelOpIdentifier(o))
	}
	idents := func(prefix string, ids []string) []string {
		out := make([]string, len(ids))
		for i, id := range ids {
			out[i] = prefix + Identifier(id)
		}
		return out
	}
	types := []idKind{
		{typeName: typeAction, prefix: typeAction, what: fieldAction, plural: "actions", parseName: "ParseAction", allName: "AllActions",
			doc: "Action is the id of an action of the closed catalogue (docs/spec/actions.yaml, 05 section 4).",
			ids: actions, idents: idents(typeAction, actions)},
		{typeName: typeEventType, prefix: "Event", what: "event type", plural: "event types", parseName: "ParseEventType", allName: "AllEventTypes",
			doc: "EventType is a durable or ephemeral event type of the catalogue (05 section 6).",
			ids: events, idents: idents("Event", events)},
		{typeName: typeOp, prefix: typeOp, what: "WebSocket op", plural: "WebSocket ops", parseName: "ParseOp", allName: "AllOps",
			doc: "Op is the name of a WebSocket op of the gateway (05 section 7, first table).",
			ids: ops, idents: idents(typeOp, ops)},
		{typeName: typeResourceKind, prefix: prefixRes, what: "resource kind", plural: "resource kinds", parseName: "ParseResourceKind", allName: "AllResourceKinds",
			doc: "ResourceKind is a resource kind named in the column \"Ressource\" of the catalogue (05 section 2.2).",
			ids: kinds, idents: idents(prefixRes, kinds)},
		{typeName: typeChannelOp, prefix: typeChannelOp, what: "terminal channel op", plural: "terminal channel ops", parseName: "ParseChannelOp", allName: "AllChannelOps",
			doc: "ChannelOp is an op of a terminal channel (05 section 7, second table) written as <channel>/<op>; it is\n// never a gateway op, even where the op name is the same.",
			ids: channelOps, idents: channelIdents},
	}
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("package authorize\n\nimport \"slices\"\n\n")
	for _, k := range types {
		writeIDKind(&b, k)
	}
	return gofmt(b.String())
}

func writeIDKind(b *strings.Builder, k idKind) {
	lower := strings.ToLower(k.typeName[:1]) + k.typeName[1:]
	fmt.Fprintf(b, "// %s\n// Obtain values only from the constants below or from %s (Semgrep rule\n", k.doc, k.parseName)
	fmt.Fprintf(b, "// bothy-go-catalog-id-conversion).\ntype %s string\n\n", k.typeName)
	fmt.Fprintf(b, "// The %s of the catalogue.\nconst (\n", k.plural)
	for i, id := range k.ids {
		fmt.Fprintf(b, "\t// %s is the %s %s.\n\t%s %s = %s\n", k.idents[i], k.what, id, k.idents[i], k.typeName, strconv.Quote(id))
	}
	b.WriteString(")\n\n")
	fmt.Fprintf(b, "// %sByID maps every id to its constant.\nvar %sByID = map[string]%s{\n", lower, lower, k.typeName)
	for i, id := range k.ids {
		fmt.Fprintf(b, "\t%s: %s,\n", strconv.Quote(id), k.idents[i])
	}
	b.WriteString(closeBlock)
	fmt.Fprintf(b, "// %sList holds every constant, sorted ascending.\nvar %sList = []%s{\n", lower, lower, k.typeName)
	for _, ident := range k.idents {
		fmt.Fprintf(b, "\t%s,\n", ident)
	}
	b.WriteString(closeBlock)
	fmt.Fprintf(b, "// %s returns the %s named s; ok is false when the catalogue has no such %s.\n", k.parseName, k.what, k.what)
	fmt.Fprintf(b, "func %s(s string) (%s, bool) {\n\tv, ok := %sByID[s]\n\treturn v, ok\n}\n\n", k.parseName, k.typeName, lower)
	fmt.Fprintf(b, "// %s returns every %s of the catalogue, sorted ascending, in a new slice on every call.\n", k.allName, k.what)
	fmt.Fprintf(b, "func %s() []%s {\n\treturn slices.Clone(%sList)\n}\n\n", k.allName, k.typeName, lower)
}

// RenderDomain renders internal/authz/domain/catalog_gen.go: the metadata of every entry as
// domain values keyed by plain strings (the domain layer may not import kernel/authorize).
func RenderDomain(c *Catalog) ([]byte, error) {
	var b strings.Builder
	b.WriteString(header)
	b.WriteString("package domain\n\n")

	b.WriteString("// actionSpecs are the actions of the catalogue by id.\nvar actionSpecs = map[string]ActionSpec{\n")
	ids := make([]string, 0, len(c.Actions))
	for _, a := range c.Actions {
		ids = append(ids, a.ID)
		f := fields{}
		f.str("ID", a.ID).strs("Resources", a.Resources, true).str("Right", a.Right).
			flag("Owner", a.Owner).flag("OwnerAsTarget", a.OwnerAsTarget).flag("StepUp", a.StepUp).
			flag("StepUpConditional", a.StepUpConditional).flag("StepUpFresh", a.StepUpFresh).
			str("Audit", a.Audit).flag("Rights", a.Rights).str("RateLimitClass", a.RateLimitClass).
			flag("System", a.System).str("Effect", a.Effect).flag("DeliveryCheck", a.DeliveryCheck).
			str("AppScope", a.AppScope)
		fmt.Fprintf(&b, entryLine, strconv.Quote(a.ID), f)
	}
	b.WriteString(closeBlock)
	writeList(&b, "actionIDs", "the ids of actionSpecs", ids)

	b.WriteString("// eventSpecs are the event types of the catalogue by type.\nvar eventSpecs = map[string]EventSpec{\n")
	types := make([]string, 0, len(c.Events))
	for _, e := range c.Events {
		types = append(types, e.Type)
		f := fields{}
		f.str("Type", e.Type).flag("Durable", e.Durable).str("Resource", e.Resource).strs("Resources", e.Resources, false).
			str("ReceiveAction", e.ReceiveAction).strs("MentionedActions", e.MentionedActions, false).
			flag("AudienceSelf", e.AudienceSelf).str("Receivers", e.Receivers).flag("ResourceVersion", e.ResourceVersion).
			str("Note", e.Note)
		fmt.Fprintf(&b, entryLine, strconv.Quote(e.Type), f)
	}
	b.WriteString(closeBlock)
	writeList(&b, "eventTypes", "the keys of eventSpecs", types)

	b.WriteString("// opSpecs are the WebSocket ops of the gateway by name.\nvar opSpecs = map[string]OpSpec{\n")
	names := make([]string, 0, len(c.Ops))
	for _, o := range c.Ops {
		names = append(names, o.Op)
		f := fields{}
		f.str("Op", o.Op).str("Direction", o.Direction).str("ActionsText", o.ActionsText).
			strs("MentionedActions", o.MentionedActions, false).flag("PerEventReceiveAction", o.PerEventReceiveAction)
		fmt.Fprintf(&b, entryLine, strconv.Quote(o.Op), f)
	}
	b.WriteString(closeBlock)
	writeList(&b, "opNames", "the keys of opSpecs", names)

	b.WriteString("// channelOpSpecs are the ops of the terminal channels by <channel>/<op>.\nvar channelOpSpecs = map[string]ChannelOpSpec{\n")
	keys := make([]string, 0, len(c.ChannelOps))
	for _, o := range c.ChannelOps {
		key := o.Channel + "/" + o.Op
		keys = append(keys, key)
		f := fields{}
		f.str("Channel", o.Channel).str("Op", o.Op).str("Direction", o.Direction).str("Action", o.Action).str("ActionText", o.ActionText)
		fmt.Fprintf(&b, entryLine, strconv.Quote(key), f)
	}
	b.WriteString(closeBlock)
	writeList(&b, "channelOpIDs", "the keys of channelOpSpecs", keys)
	writeList(&b, "resourceKinds", "the resource kinds of all actions and event types", c.ResourceKinds)
	return gofmt(b.String())
}

// fields renders the non-zero fields of a composite literal.
type fields []string

func (f *fields) str(name, v string) *fields {
	if v != "" {
		*f = append(*f, name+": "+strconv.Quote(v))
	}
	return f
}

// strs renders a string slice; keepEmpty writes an empty non-nil slice (an action whose resource
// is "as the target action" has no kind, which differs from a missing value only in the source).
func (f *fields) strs(name string, v []string, keepEmpty bool) *fields {
	if len(v) == 0 && !keepEmpty {
		return f
	}
	q := make([]string, len(v))
	for i, s := range v {
		q[i] = strconv.Quote(s)
	}
	*f = append(*f, name+": []string{"+strings.Join(q, ", ")+"}")
	return f
}

func (f *fields) flag(name string, v bool) *fields {
	if v {
		*f = append(*f, name+": true")
	}
	return f
}

func (f fields) String() string { return strings.Join(f, ", ") }

func writeList(b *strings.Builder, name, doc string, items []string) {
	fmt.Fprintf(b, "// %s are %s, sorted ascending.\nvar %s = []string{\n", name, doc, name)
	for _, s := range items {
		fmt.Fprintf(b, "\t%s,\n", strconv.Quote(s))
	}
	b.WriteString(closeBlock)
}

func gofmt(src string) ([]byte, error) {
	out, err := format.Source([]byte(src))
	if err != nil {
		return nil, fmt.Errorf("catalogen: format generated code: %w", err)
	}
	return out, nil
}
